import {
  isProgramError,
  type Address,
  type HasAddress,
  type SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM,
  type SolanaError,
} from "@solana/kit";
import { SWAP_PROGRAM_ADDRESS } from "../programs";

/** InvalidAmount: Amount must be greater than zero */
export const SWAP_ERROR__INVALID_AMOUNT = 0x1770; // 6000

export type SwapError = typeof SWAP_ERROR__INVALID_AMOUNT;

let swapErrorMessages: Record<SwapError, string> | undefined;
if (process.env["NODE_ENV"] !== "production") {
  swapErrorMessages = {
    [SWAP_ERROR__INVALID_AMOUNT]: `Amount must be greater than zero`,
  };
}

export function getSwapErrorMessage(code: SwapError): string {
  if (process.env["NODE_ENV"] !== "production") {
    return (swapErrorMessages as Record<SwapError, string>)[code];
  }

  return "Error message not available in production bundles.";
}

export function isSwapError<TProgramErrorCode extends SwapError>(
  error: unknown,
  transactionMessage: {
    instructions: Record<number, { programAddress: Address }>;
  },
  code?: TProgramErrorCode,
  config: { programAddress?: Address | HasAddress } = {},
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  const programAddressInput = config.programAddress ?? SWAP_PROGRAM_ADDRESS;
  const programAddress =
    typeof programAddressInput === "string"
      ? programAddressInput
      : programAddressInput.address;
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    programAddress,
    code,
  );
}
